import { useState, useMemo } from 'react';

export const useUsers = (initialUsers: any[]) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [sortConfig, setSortConfig] = useState<{ key: string; dir: 'asc' | 'desc' } | null>(null);

  const filteredAndSortedUsers = useMemo(() => {
    let result = [...initialUsers];

    // Filter
    if (searchTerm) {
      result = result.filter(user => 
        Object.values(user).some(val => 
          String(val).toLowerCase().includes(searchTerm.toLowerCase())
        )
      );
    }

    // Sort
    if (sortConfig) {
      result.sort((a, b) => {
        const aValue = a[sortConfig.key];
        const bValue = b[sortConfig.key];
        if (aValue < bValue) return sortConfig.dir === 'asc' ? -1 : 1;
        if (aValue > bValue) return sortConfig.dir === 'asc' ? 1 : -1;
        return 0;
      });
    }

    return result;
  }, [initialUsers, searchTerm, sortConfig]);

  const requestSort = (key: string) => {
    let dir: 'asc' | 'desc' = 'asc';
    if (sortConfig?.key === key && sortConfig.dir === 'asc') {
      dir = 'desc';
    }
    setSortConfig({ key, dir });
  };

  return { searchTerm, setSearchTerm, filteredAndSortedUsers, requestSort };
};
